"""Render docs/languages.md and DICTIONARY_LICENSES.md from the release catalog.

Run from any directory after the catalog changes; ``--check`` exits non-zero
when a committed page is stale.
"""

from __future__ import annotations

import argparse
import sys
from collections import Counter
from pathlib import Path

from common import license_class, read_json

ROOT = Path(__file__).resolve().parent.parent
CATALOG = ROOT / "dictionaries" / "catalog"
LANGUAGES = ROOT / "docs" / "languages.md"
LICENSES = ROOT / "DICTIONARY_LICENSES.md"
GENERATED = (
    "<!-- Generated by dictionaries/pages.py from dictionaries/catalog, "
    "dictionaries/sources.json and dictionaries/policy.json; do not edit. -->"
)

LANGUAGES_INTRO = """\
# Languages and accuracy

{generated}

The v{version} release has a dictionary package for {packages} languages.
Accuracy is exact lemma match on the gold tokens of Universal Dependencies 2.19,
as scored by [`dictionaries/evaluate.py`](../dictionaries/evaluate.py). *Copy*
is the accuracy of returning every token unchanged.

| Scored on | Languages | Macro accuracy, % | Copy, % |
| --- | ---: | ---: | ---: |
| test | {official} | {official_macro} | {official_copy} |
| 2-fold | {twofold} | {twofold_macro} | {twofold_copy} |
| — | {unscored} | — | — |

- **test**: the official test split. The dictionary learned from train; dev
  chose its options and then joined the final refit.
- **test†** ({no_dev} languages): as *test*, but the treebank has no dev split,
  so the options were chosen on a stand-in carved from the training split (see
  [Data use](../dictionaries/README.md#data-use)).
- **2-fold**: the treebank has no training split. It is cut into two halves (by
  document where the treebank marks documents, otherwise by sentence, so halves
  may share a document) and each half is scored by a build that learned from the
  other. The shipped package learned from the whole treebank. These treebanks
  are small, often a few hundred sentences, so the estimate is noisy.
- **—**: no gold lemmas. The package holds dictionary entries only; its accuracy
  is unmeasured.

For languages without an official dev split (test† and 2-fold), the dev
stand-in was introduced after the first test evaluation, so their scores are
partly exploratory.

Packages ending in `-nc` are for non-commercial use only; see
[DICTIONARY_LICENSES.md](../DICTIONARY_LICENSES.md). The build report, with the
dictionary order chosen on dev and the gate statistics, is
[`dictionaries/catalog/EVALUATION.md`](../dictionaries/catalog/EVALUATION.md).

| Code | Language | Package | License | Scored on | Accuracy, % | Copy, % \
| Gold tokens | Treebank |
| --- | --- | --- | --- | --- | ---: | ---: | ---: | --- |
"""

LICENSES_PAGE = """\
# Dictionary licenses

{generated}

The udlex code is MIT. The dictionary packages are data with their own licenses,
which follow from the sources they were built from. The rules are in
[`dictionaries/README.md`](dictionaries/README.md#licenses); this page lists what
they gave for release v{version}.

## How a package gets its license

- Every table keeps the license of its source. The corpus tables (`exact`,
  `lower`, `rules`, `entities`) are learned from the anchor treebank and carry
  its license. Each row of the `external` table comes from exactly one
  dictionary and carries that dictionary's license.
- A package with a non-commercial part is named `udlex-dict-<iso>-nc` and is
  released as a whole under CC-BY-NC-SA-4.0. Otherwise the package takes the
  strictest license of its parts.
- Each wheel and archive holds the treebank README and LICENSE, a `NOTICE` with
  the attribution of every input, and `SOURCES.json`. Like spaCy's `meta.json`,
  `SOURCES.json` lists each source with name, URL, version, author and SPDX
  license, and the files it fills. The same metadata for every package is in
  [`dictionaries/catalog/DICTIONARIES.json`](dictionaries/catalog/DICTIONARIES.json).

If you redistribute a package, keep its `NOTICE` and `SOURCES.json` and follow
its license.

## Package licenses

| License | Packages |
| --- | ---: |
{license_rows}

Non-commercial packages ({nc_count}): {nc_list}.

Of these, {review_count} also carry `requires_license_review`: the treebank's
README and LICENSE disagree, or [`policy.json`](dictionaries/policy.json) lists
the treebank for review: {review_list}.

Packages whose treebank states extra conditions:

{special_rows}

Per-package licenses are also listed in [docs/languages.md](docs/languages.md).

## Treebanks

{treebank_count} packages learned from a Universal Dependencies 2.19 treebank
(<https://universaldependencies.org/>). The licenses of those treebanks:

| Treebank license | Packages |
| --- | ---: |
{treebank_rows}

## Dictionaries

*Packages* counts the packages in which the source contributed rows; 0 means
it was a build input but no shipped package took rows from it. Wiktionary
editions other than English are merged into one `wiktionary-other` table per
package.

| Source | Attribution | License | Version | Home | Packages |
| --- | --- | --- | --- | --- | ---: |
{source_rows}

## Left out

Sources with a copyleft or unclear license are not used
(`excluded_license_classes` in [`policy.json`](dictionaries/policy.json)):

| Source | License | Class |
| --- | --- | --- |
{left_out_rows}

Also left out for some languages, because their part of a source has another
license: {by_language}. Excluded by policy: {excluded}.
"""


def percent(hits: int, total: int) -> str:
    """Accuracy cell with two decimals."""
    return f"{100 * hits / total:.2f}"


def mean(values: list[float]) -> str:
    """Macro average cell."""
    return f"{sum(values) / len(values):.2f}"


def has_dev(entry: dict) -> bool:
    """Whether the anchor treebank ships an official dev split."""
    files = (entry["corpus"] or {}).get("files", [])
    return any("-ud-dev." in item["name"] for item in files)


def scored_on(entry: dict) -> str:
    """Evaluation cell: test, test without dev, 2-fold or unscored."""
    if entry["evaluation"] == "test":
        return "test" if has_dev(entry) else "test†"
    return "2-fold" if entry["evaluation"] == "two-fold" else "—"


def languages_page(catalog: list[dict], evaluation: dict) -> str:
    """The per-language accuracy table with its group averages."""
    scores = {row["iso639_3"]: row for row in evaluation["languages"]}
    accuracy: dict[str, list[float]] = {"official": [], "twofold": []}
    copying: dict[str, list[float]] = {"official": [], "twofold": []}
    rows = []
    for entry in sorted(catalog, key=lambda item: item["iso639_3"]):
        score = scores.get(entry["iso639_3"])
        cells = ["—", "—", "—"]
        if score is not None:
            total = score["tokens"]
            accuracy[score["mode"]].append(100 * score["new"] / total)
            copying[score["mode"]].append(100 * score["copy"] / total)
            cells = [
                percent(score["new"], total),
                percent(score["copy"], total),
                f"{total:,}",
            ]
        treebank = (entry["corpus"] or {}).get("treebank", "—")
        rows.append(
            f"| {entry['iso639_3']} | {entry['language']} | "
            f"`{entry['distribution']}` | {entry['license']} | {scored_on(entry)} | "
            + " | ".join(cells)
            + f" | {treebank} |"
        )
    # The page must agree with the evaluation receipt it is rendered from.
    for mode, key in (("official", "official"), ("twofold", "two-fold")):
        expected = evaluation["summary"][key]
        assert len(accuracy[mode]) == expected["languages"]
        assert abs(float(mean(accuracy[mode])) - expected["macro"]["new"]) < 0.005
    intro = LANGUAGES_INTRO.format(
        generated=GENERATED,
        version=catalog[0]["dictionary_version"],
        packages=len(catalog),
        official=len(accuracy["official"]),
        official_macro=mean(accuracy["official"]),
        official_copy=mean(copying["official"]),
        twofold=len(accuracy["twofold"]),
        twofold_macro=mean(accuracy["twofold"]),
        twofold_copy=mean(copying["twofold"]),
        unscored=len(catalog) - len(scores),
        no_dev=sum(scored_on(entry) == "test†" for entry in catalog),
    )
    return intro + "\n".join(rows) + "\n"


def licenses_page(catalog: list[dict], sources: list[dict], policy: dict) -> str:
    """Package licenses, the sources behind them and what was left out."""
    by_iso = sorted(catalog, key=lambda entry: entry["iso639_3"])
    nc = [entry for entry in by_iso if entry["noncommercial"]]
    review = [entry["iso639_3"] for entry in nc if entry["requires_license_review"]]
    corpus = [s for e in catalog for s in e["sources"] if s["part"] == "corpus"]
    used = Counter(
        s["name"] for e in catalog for s in e["sources"] if s["part"] != "corpus"
    )
    kept, left_out = [], []
    for source in sorted(sources, key=lambda item: item["id"]):
        cls = license_class(source["license"])
        if cls in policy["excluded_license_classes"]:
            left_out.append(f"| `{source['id']}` | {source['license']} | {cls} |")
        else:
            kept.append(
                f"| `{source['id']}` | {source['attribution']} | {source['license']} "
                f"| {source['revision']} | <{source['home']}> | {used[source['id']]} |"
            )

    def table(counts: Counter[str]) -> str:
        return "\n".join(f"| {name} | {n} |" for name, n in counts.most_common())

    return LICENSES_PAGE.format(
        generated=GENERATED,
        version=catalog[0]["dictionary_version"],
        license_rows=table(Counter(entry["license"] for entry in catalog)),
        nc_count=len(nc),
        nc_list=", ".join(f"`{entry['distribution']}`" for entry in nc),
        review_count=len(review),
        review_list=", ".join(f"`{iso}`" for iso in review),
        special_rows="\n".join(
            f"- `{entry['distribution']}` ({entry['license']}): "
            f"{entry['special_conditions']}"
            for entry in by_iso
            if entry["special_conditions"]
        ),
        treebank_count=len(corpus),
        treebank_rows=table(Counter(source["license"] for source in corpus)),
        source_rows="\n".join(kept),
        left_out_rows="\n".join(left_out),
        by_language="; ".join(
            f"`{source['id']}` for {iso} ({spdx or 'no license'})"
            for source in sorted(sources, key=lambda item: item["id"])
            for iso, spdx in sorted(source.get("license_by_language", {}).items())
            if license_class(spdx) in policy["excluded_license_classes"]
        ),
        excluded=", ".join(
            f"`{name}`" + ("" if scope == "*" else f" for {', '.join(scope)}")
            for name, scope in sorted(policy["excluded_sources"].items())
        ),
    )


def main() -> int:
    """Write the pages, or with ``--check`` report the stale ones."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="fail if stale")
    args = parser.parse_args()
    catalog = read_json(CATALOG / "DICTIONARIES.json")["dictionaries"]
    pages = {
        LANGUAGES: languages_page(catalog, read_json(CATALOG / "evaluation.json")),
        LICENSES: licenses_page(
            catalog,
            read_json(ROOT / "dictionaries" / "sources.json")["sources"],
            read_json(ROOT / "dictionaries" / "policy.json"),
        ),
    }
    stale = [
        path
        for path, text in pages.items()
        if not path.exists() or path.read_text(encoding="utf-8") != text
    ]
    if args.check:
        for path in stale:
            print(f"stale: {path.relative_to(ROOT)}", file=sys.stderr)
        return 1 if stale else 0
    for path in stale:
        path.write_text(pages[path], encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
